package net.spell_engine.api.spell;

import net.minecraft.component.ComponentType;
import net.minecraft.registry.Registries;
import net.minecraft.registry.Registry;
import net.minecraft.util.Identifier;
import net.spell_engine.SpellEngineMod;
import net.spell_engine.api.spell.container.SpellChoice;
import net.spell_engine.api.spell.container.SpellContainer;

import java.util.function.UnaryOperator;

public class SpellDataComponents {
    public static final ComponentType<SpellContainer> SPELL_CONTAINER = register(Identifier.of(SpellEngineMod.ID, "spell_container"),
            builder -> builder.codec(SpellContainer.CODEC)
    );
    public static final ComponentType<SpellChoice> SPELL_CHOICE = register(Identifier.of(SpellEngineMod.ID, "spell_choice"),
            builder -> builder.codec(SpellChoice.CODEC)
    );
    public static final ComponentType<Identifier> EQUIPMENT_SET = register(Identifier.of(SpellEngineMod.ID, "equipment_set"),
            builder -> builder.codec(Identifier.CODEC)
    );
    public static final ComponentType<Identifier> ITEM_MODEL = register(Identifier.of(SpellEngineMod.ID, "item_model"),
            builder -> builder.codec(Identifier.CODEC)
    );

    private static <T> ComponentType<T> register(Identifier id, UnaryOperator<ComponentType.Builder<T>> builderOperator) {
        return Registry.register(Registries.DATA_COMPONENT_TYPE, id, ((ComponentType.Builder)builderOperator.apply(ComponentType.builder())).build());
    }
}

package net.spell_engine.api.spell.container;

import com.mojang.serialization.Codec;
import com.mojang.serialization.codecs.RecordCodecBuilder;
import net.minecraft.util.Identifier;
import org.jetbrains.annotations.Nullable;

import java.util.ArrayList;
import java.util.List;

public record SpellContainer(
        /// Defines what spells this container can resolve for spell casting.
        /// (Serves to avoid using archery spells in melee weapons, etc.)
        ContentType access,
        /// Additional parameter for access type. Currently supported:
        /// - `access` with the value of: `TAG` - this would be the tag ID to use
        String access_param,
        /// Pool (spell tag) of spells this container can be assigned to.
        /// For example: `#wizards:fire`
        String pool,
        /// Restrict the container to provide its access only when equipped in a specified slot.
        /// For example: `off_hand` for shield specific spells
        /// If absent, no restriction is applied.
        String slot,
        /// Maximum number of spells that can be assigned to this container.
        int max_spell_count,
        /// List of spells by ID, this container currently holds.
        List<String> spell_ids,
        /// The number of additional spells per tier can be bound to this container.
        int extra_tier_binding) {
    public enum ContentType {
        ANY,
        NONE,
        MAGIC,
        ARCHERY,
        CONTAINED,
        TAG;
        public static Codec<ContentType> CODEC = Codec.STRING.xmap(ContentType::valueOf, ContentType::name);
    }

    /// Normalizes a spell ID string to be a valid Minecraft identifier path.
    /// Lowercases the input and strips any character not valid for identifiers.
    public static String normalizeId(String id) {
        return id.toLowerCase().replaceAll("[^a-z0-9/._:-]", "");
    }

    public static final Codec<SpellContainer> CODEC = RecordCodecBuilder.create(instance -> instance.group(
            ContentType.CODEC.optionalFieldOf("access", ContentType.NONE).forGetter(x -> x.access),
            Codec.STRING.optionalFieldOf("access_param", "").forGetter(x -> x.access_param),
            Codec.STRING.optionalFieldOf("pool", "").forGetter(x -> x.pool),
            Codec.STRING.optionalFieldOf("slot", "").forGetter(x -> x.slot),
            Codec.INT.optionalFieldOf("max_spell_count", 0).forGetter(x -> x.max_spell_count),
            Codec.STRING.listOf().optionalFieldOf("spell_ids", List.of()).forGetter(x -> x.spell_ids),
            Codec.INT.optionalFieldOf("extra_tier_binding", 0).forGetter(x -> x.extra_tier_binding)
    ).apply(instance, SpellContainer::new));

    public static final SpellContainer EMPTY = new SpellContainer(ContentType.NONE, "", "", "", 0, List.of(), 0);

    // Canonical constructor with default values, to avoid null values
    public SpellContainer(ContentType content, String access_tag, String pool, int max_spell_count, List<String> spell_ids) {
        this(content, access_tag, pool, "", max_spell_count, spell_ids, 0);
    }

    public SpellContainer(ContentType content, String access_tag, String pool, String slot, int max_spell_count, List<String> spell_ids) {
        this(content, access_tag, pool, slot, max_spell_count, spell_ids, 0);
    }

    public SpellContainer(ContentType access, String access_param, String pool, String slot, int max_spell_count, List<String> spell_ids, int extra_tier_binding) {
        this.access = access != null ? access : ContentType.NONE;
        this.access_param = access_param;
        this.pool = pool != null ? pool : "";
        this.slot = slot != null ? slot : "";
        this.max_spell_count = max_spell_count;
        this.spell_ids = spell_ids != null ? spell_ids.stream().map(SpellContainer::normalizeId).toList() : List.of();
        this.extra_tier_binding = extra_tier_binding;
    }

    // MARK: Helpers

    public int binding_mutex_count() {
        return Math.max(0, extra_tier_binding + 1);
    }

    public boolean isResolver() {
        if (access == null) {
            return false;
        }
        switch (access) {
            case NONE -> { return false; }
            case TAG -> { return !access_param.isEmpty(); }
            default -> { return true; }
        }
    }

    public boolean isValid() {
        if (isResolver()) {
            return true;
        }
        if (max_spell_count < 0) {
            return false;
        }
        return !spell_ids.isEmpty() || (pool != null && !pool.isEmpty());
    }

    public boolean contains(Identifier spellId) {
        return spell_ids.contains(spellId.toString());
    }

    public boolean slotMatches(@Nullable String other) {
        return other == null || this.slot().contains(other);
    }

    public boolean isUsable() {
        return isValid() && !spell_ids.isEmpty();
    }

    public SpellContainer copy() {
        return new SpellContainer(access, access_param, pool, slot, max_spell_count, new ArrayList<>(spell_ids), extra_tier_binding);
    }

    public SpellContainer copyWith(List<String> spell_ids) {
        return new SpellContainer(access, access_param, pool, slot, max_spell_count, spell_ids, extra_tier_binding);
    }

    public SpellContainer withContentType(ContentType content) {
        return new SpellContainer(content, access_param, pool, slot, max_spell_count, spell_ids, extra_tier_binding);
    }

    public SpellContainer withBindingPool(Identifier poolId) {
        return new SpellContainer(access, access_param, poolId.toString(), slot, max_spell_count, spell_ids, extra_tier_binding);
    }

    public SpellContainer withMaxSpellCount(int maxSpellCount) {
        return new SpellContainer(access, access_param, pool, slot, maxSpellCount, spell_ids, extra_tier_binding);
    }

    public SpellContainer withSpell(String spellId) {
        return new SpellContainer(access, access_param, pool, slot, max_spell_count, List.of(spellId), extra_tier_binding);
    }

    public SpellContainer withSpellId(Identifier spellId) {
        return new SpellContainer(access, access_param, pool, slot, max_spell_count, List.of(spellId.toString()), extra_tier_binding);
    }

    public SpellContainer withSpellIds(List<Identifier> spellIds) {
        var spellIdStrings = spellIds.stream().map(Identifier::toString).toList();
        return new SpellContainer(access, access_param, pool, slot, max_spell_count, spellIdStrings, extra_tier_binding);
    }

    public SpellContainer withAdditionalSpell(List<String> spellIds) {
        var newSpellIds = new ArrayList<>(spell_ids);
        newSpellIds.addAll(spellIds);
        return new SpellContainer(access, access_param, pool, slot, max_spell_count, newSpellIds, extra_tier_binding);
    }
}

package net.spell_engine.api.spell.container;

import net.minecraft.item.ItemStack;
import net.minecraft.registry.entry.RegistryEntry;
import net.minecraft.util.Identifier;
import net.minecraft.world.World;
import net.spell_engine.api.spell.*;
import net.spell_engine.api.spell.registry.SpellRegistry;
import net.spell_engine.internals.container.SpellAssignments;

import java.util.*;
import java.util.stream.Collectors;

public class SpellContainerHelper {

    // Read helpers

    public static SpellContainer containerFromItemStack(ItemStack itemStack) {
        if (itemStack.isEmpty()) {
            return null;
        }
        var component = itemStack.get(SpellDataComponents.SPELL_CONTAINER);
        if (component != null) {
            return component;
        }
        var id = itemStack.getItem().getRegistryEntry().getKey().get().getValue();
        return SpellAssignments.containerForItem(id);
    }

    public static Identifier getPoolId(SpellContainer container) {
        if (container != null && container.pool() != null) {
            return Identifier.of(container.pool());
        }
        return null;
    }

    public static boolean contains(SpellContainer container, Identifier spellId) {
        return container != null && container.spell_ids().contains(spellId.toString());
    }

    // Misc helpers (Spell Binding)

    public static List<String> sortedSpells(World world, List<String> spellIds) {
        HashMap<Identifier, Spell> spells = new HashMap<>();
        for (var idString : spellIds) {
            var id = Identifier.of(idString);
            var spellEntry = SpellRegistry.from(world).getEntry(id).orElse(null);
            if (spellEntry != null) {
                spells.put(id, spellEntry.value());
            }
        }
        return spells.entrySet().stream()
                .sorted(SpellContainerHelper.containerSorter)
                .map(entry -> entry.getKey().toString())
                .collect(Collectors.toList());
    }

    public static SpellContainer addSpell(World world, Identifier spellId, SpellContainer container) {
        var spellIds = new ArrayList<String>(container.spell_ids());
        spellIds.add(spellId.toString());
        return container.copyWith(sortedSpells(world, spellIds));
    }

    public static void addSpell(World world, Identifier spellId, ItemStack itemStack) {
        var container = containerFromItemStack(itemStack);
        if (container == null || !container.isValid()) {
            System.err.println("Trying to add spell: " + spellId + " to an ItemStack without valid spell container");
            return;
        }
        var modifiedContainer = addSpell(world, spellId, container);
        itemStack.set(SpellDataComponents.SPELL_CONTAINER, modifiedContainer);
    }

    public static SpellContainer removeSpell(World world, Identifier spellId, SpellContainer container) {
        var spellIds = new ArrayList<String>(container.spell_ids());
        spellIds.remove(spellId.toString());
        return container.copyWith(sortedSpells(world, spellIds));
    }

    public static void removeSpell(World world, Identifier spellId, ItemStack itemStack) {
        var container = containerFromItemStack(itemStack);
        if (container == null || !container.isValid()) {
            System.err.println("Trying to remove spell: " + spellId + " from an ItemStack without valid spell container");
            return;
        }
        var modifiedContainer = removeSpell(world, spellId, container);
        itemStack.set(SpellDataComponents.SPELL_CONTAINER, modifiedContainer);
    }

    // Sorting
    //
    // Two regimes, deliberately different. A *container* is read like a hotbar (one wielder, quality is all
    // that matters), a *catalog* is browsed like a library (every mod's spells at once, laid out by origin).

    /// How the spells of a single container are ordered: by quality alone, since they are read as a
    /// hotbar, where what a spell costs its wielder to reach matters more than where it came from.
    public static final Comparator<Map.Entry<Identifier, Spell>> containerSorter = Comparator
            .comparingInt((Map.Entry<Identifier, Spell> entry) -> entry.getValue().tier)
            .thenComparingInt(entry -> entry.getValue().sub_tier)
            .thenComparing(entry -> entry.getKey().toString());

    /// How spells are ordered when a catalog of them is browsed - the spell binding table, the creative
    /// menu. Unlike a container, a catalog holds the spells of every mod at once, but it is still laid out
    /// tier-first: the binding table lays each tier out as its own row, so the catalog is sorted flat and
    /// chunked into rows by tier, and tier-adjacent spells must stay contiguous no matter which mod they
    /// come from. Only within a tier does mod (namespace) group spells together, and `group` order them
    /// inside a row. Without tier leading, a high-tier spell from a namespace that sorts early (e.g. a
    /// tier-5 spell) would jump into the first row instead of the last.
    public static int compareInCatalog(Identifier id1, Spell spell1, Identifier id2, Spell spell2) {
        var byTier = Integer.compare(spell1.tier, spell2.tier);
        if (byTier != 0) {
            return byTier;
        }
        var byNamespace = id1.getNamespace().compareTo(id2.getNamespace());
        if (byNamespace != 0) {
            return byNamespace;
        }
        var byGroup = groupOf(spell1).compareTo(groupOf(spell2));
        if (byGroup != 0) {
            return byGroup;
        }
        var bySubTier = Integer.compare(spell1.sub_tier, spell2.sub_tier);
        if (bySubTier != 0) {
            return bySubTier;
        }
        return id1.getPath().compareTo(id2.getPath());
    }

    /// Defaults to empty, but JSON is free to spell the group out as `null`, which no ordering survives.
    private static String groupOf(Spell spell) {
        return spell.group != null ? spell.group : "";
    }

    /// `compareInCatalog` over map entries, for streams keyed by spell id.
    public static final Comparator<Map.Entry<Identifier, Spell>> catalogSorter = (entry1, entry2) ->
            compareInCatalog(entry1.getKey(), entry1.getValue(), entry2.getKey(), entry2.getValue());

    /// `compareInCatalog` over registry entries, for streams straight off the spell registry.
    public static final Comparator<RegistryEntry<Spell>> catalogEntrySorter = (entry1, entry2) ->
            compareInCatalog(entry1.getKey().get().getValue(), entry1.value(),
                    entry2.getKey().get().getValue(), entry2.value());

    // Container queries

    public static boolean hasValidContainer(ItemStack itemStack) {
        return containerFromItemStack(itemStack) != null;
    }

    public static boolean hasBindableContainer(ItemStack itemStack) {
        var container = containerFromItemStack(itemStack);
        return container != null && container.pool() != null && !container.pool().isEmpty();
    }

    public static boolean hasUsableContainer(ItemStack itemStack) {
        var container = containerFromItemStack(itemStack);
        return container != null && (container.isUsable() || container.isResolver());
    }

    public static int poolTierSize(List<RegistryEntry<Spell>> spells) {
        var tiers = new HashSet<Integer>();
        for (var spellEntry : spells) {
            var spell = spellEntry.value();
            tiers.add(spell.tier);
        }
        return tiers.size();
    }
}

package net.spell_engine.internals.container;
import net.spell_engine.Platform;

import net.minecraft.entity.EquipmentSlot;
import net.minecraft.entity.player.PlayerEntity;
import net.minecraft.item.ItemStack;
import net.minecraft.registry.entry.RegistryEntry;
import net.minecraft.registry.tag.TagKey;
import net.minecraft.server.network.ServerPlayerEntity;
import net.minecraft.util.Identifier;
import net.minecraft.world.World;
import net.spell_engine.SpellEngineMod;
import net.spell_engine.api.item.set.EquipmentSet;
import net.spell_engine.api.spell.Spell;
import net.spell_engine.api.spell.container.SpellContainer;
import net.spell_engine.api.spell.container.SpellContainerHelper;
import net.spell_engine.api.spell.registry.SpellRegistry;
import net.spell_engine.internals.casting.SpellCaster;
import net.spell_engine.network.Packets;
import org.jetbrains.annotations.Nullable;

import java.util.*;

public class SpellContainerSource {
    public record Result(
            SpellContainer activeContainer,
            List<RegistryEntry<Spell>> actives,
            List<RegistryEntry<Spell>> passives,
            List<RegistryEntry<Spell>> modifiers,
            List<SpellContainerSource.SourcedContainer> sources) {
        public static final Result EMPTY = new Result(SpellContainer.EMPTY, List.of(), List.of(), List.of(), List.of());
    }
    public interface Owner {
        Map<String, List<SourcedContainer>> spellContainerCache();
        Map<Identifier, List<Spell.Modifier>> spellModifierCache();
        LinkedHashMap<String, SpellContainer> serverSideSpellContainers();
        void markServerSideSpellContainersDirty();
        void setSpellContainers(Result result);
        Result getSpellContainers();
    }
    public static SpellContainer activeContainerOf(PlayerEntity player) {
        return ((Owner)player).getSpellContainers().activeContainer;
    }
    public static List<RegistryEntry<Spell>> activeSpellsOf(PlayerEntity player) {
        return ((Owner)player).getSpellContainers().actives;
    }
    public static List<RegistryEntry<Spell>> passiveSpellsOf(PlayerEntity player) {
        return ((Owner)player).getSpellContainers().passives;
    }
    public static Result getSpellsOf(PlayerEntity player) {
        return ((Owner)player).getSpellContainers();
    }
    public static void setDirty(PlayerEntity player, Entry source) {
        setDirty(player, source.name());
    }
    public static void setDirty(PlayerEntity player, ItemEntry source) {
        setDirty(player, source.name());
    }
    public static void setDirty(PlayerEntity player, String source) {
        ((Owner)player).spellContainerCache().remove(source);
    }
    public static void setDirtyServerSide(PlayerEntity player) {
        ((Owner)player).markServerSideSpellContainersDirty();
    }
    public static void syncServerSideContainers(PlayerEntity player) {
        if (!player.getWorld().isClient) {
            var containers = ((Owner)player).serverSideSpellContainers();
            var packet = new Packets.SpellContainerSync(containers);
            Platform.util().networkS2C_Send((ServerPlayerEntity) player, packet);
            setDirty(player, MAIN_HAND);
        }
    }

    public interface DirtyChecker {
        Object current(PlayerEntity player);
    }
    public record SourcedContainer(String name, @Nullable ItemStack itemStack, SpellContainer container) { }
    public interface Source {
        List<SourcedContainer> getSpellContainers(PlayerEntity player, String name);
    }
    public record Entry(String name, Source source, @Nullable DirtyChecker checker) { }
    public static final List<Entry> sources = new ArrayList<>();
    private static Entry entry(String name, Source source) {
        return entry(name, source, null);
    }
    private static Entry entry(String name, Source source, @Nullable DirtyChecker dirtyChecker) {
        var newEntry = new Entry(name, source, dirtyChecker);
        sources.add(newEntry);
        return newEntry;
    }

    public interface ItemStackSource extends Source {
        List<ItemStack> getSpellContainerItemStacks(PlayerEntity player, String name);
        @Override
        default List<SourcedContainer> getSpellContainers(PlayerEntity player, String name) {
            var itemStacks = getSpellContainerItemStacks(player, name);
            var sources = new ArrayList<SourcedContainer>();
            for (var itemStack : itemStacks) {
                SpellContainer container = SpellContainerHelper.containerFromItemStack(itemStack);
                if (container != null && container.isValid()) {
                    sources.add(new SpellContainerSource.SourcedContainer(name, itemStack, container));
                }
            }
            return sources;
        }
    }
    public record ItemEntry(String name, ItemStackSource source, @Nullable DirtyChecker checker) {
        public static ItemEntry of(String name, ItemStackSource source, @Nullable DirtyChecker dirtyChecker) {
            return new ItemEntry(name, source, dirtyChecker);
        }
        public static ItemEntry of(String name, ItemStackSource source)  {
            return of(name, source, player -> source.getSpellContainerItemStacks(player, name));
        }
    }
    public static final List<ItemEntry> itemSources = new ArrayList<>();
    private static ItemEntry itemEntry(String name, ItemStackSource source) {
        var newEntry = ItemEntry.of(name, source);
        addItemSource(newEntry);
        return newEntry;
    }

//    private static void addSourceIfValid(ItemStack fromItemStack, List<SourcedContainer> sources, String name) {
//        SpellContainer container = SpellContainerHelper.containerFromItemStack(fromItemStack);
//        if (container != null && container.isValid()) {
//            sources.add(new SpellContainerSource.SourcedContainer(name, fromItemStack, container));
//        }
//    }

    public static void addSource(Entry entry) {
        sources.add(entry);
    }
    public static void addSource(Entry entry, @Nullable String after) {
        boolean added = false;
        if (after != null) {
            // Index of the entry with the name `after`
            int index = -1;
            for (int i = 0; i < sources.size(); i++) {
                if (sources.get(i).name().equals(after)) {
                    index = i;
                    break;
                }
            }
            if (index != -1) {
                sources.add(index + 1, entry);
                added = true;
            }
        }
        if (!added) {
            sources.add(entry);
        }
    }
    public static void addItemSource(ItemEntry entry) {
        addItemSource(entry, null);
    }
    public static void addItemSource(ItemEntry entry, @Nullable String after) {
        itemSources.add(entry);
        addSource(new Entry(entry.name(), entry.source(), entry.checker()), after);
    }

    public static final ItemEntry MAIN_HAND = itemEntry("main_hand", (player, sourceName) -> {
        return List.of(player.getMainHandStack());
    });
    public static final ItemEntry OFF_HAND = itemEntry("off_hand", (player, sourceName) -> {
        return List.of(player.getOffHandStack());
    });
    public static final ItemEntry ARMOR = itemEntry("armor", (player, sourceName) -> {
        return List.of(player.getInventory().armor.get(0), player.getInventory().armor.get(1),
                player.getInventory().armor.get(2), player.getInventory().armor.get(3));
    });

    public static void init() {
    }

    public static void update(PlayerEntity player) {
        var owner = (Owner)player;
        var allContainers = new ArrayList<SourcedContainer>();
        boolean updated = false;

        if (SpellEngineMod.config.spell_container_caching) {
            for (var entry : sources) {
                var resolvedContainers = owner.spellContainerCache().get(entry.name());
                if (resolvedContainers != null) {
                    allContainers.addAll(resolvedContainers);
                } else {
                    // System.out.println("Container source dirty: " + entry.name() + " for " + player.getName());
                    var freshContainers = entry.source().getSpellContainers(player, entry.name());
                    allContainers.addAll(freshContainers);
                    owner.spellContainerCache().put(entry.name(), freshContainers);
                    updated = true;
                }
            }
        } else {
            for (var entry : sources) {
                var freshContainers = entry.source().getSpellContainers(player, entry.name());
                allContainers.addAll(freshContainers);
            }
            updated = true;
        }
        for (var entry: owner.serverSideSpellContainers().entrySet()) {
            allContainers.add(new SourcedContainer(entry.getKey(), null, entry.getValue()));
        }

        if (updated) {
            owner.spellModifierCache().clear();
            // Updates active equipment sets on the player (attribute set bonuses),
            // appends to `allContainers` from active equipment sets (spell set bonuses)
            updateEquipmentSets(player, allContainers);

            // System.out.println("Updating spell containers for " + player.getName());
            var heldItemStack = player.getMainHandStack();
            var heldContainer = SpellContainerHelper.containerFromItemStack(heldItemStack);
            var activeContainer = SpellContainer.EMPTY;
            List<RegistryEntry<Spell>> activeSpells = List.of();
            if (heldContainer != null && heldContainer.isResolver()) {
                var merged = mergedContainerSources1(allContainers, heldContainer, Spell.Type.ACTIVE, player.getWorld());
                activeContainer = merged.container();
                activeSpells = merged.spells();
            }
            List<RegistryEntry<Spell>> passiveSpells = mergedContainerSources(allContainers, null, null, Spell.Type.PASSIVE, player.getWorld());

            var registry = SpellRegistry.from(player.getWorld());
            LinkedHashSet<RegistryEntry<Spell>> modifiers = new LinkedHashSet<>();
            for (var container : allContainers) {
                var spellContainer = container.container();
                for (var idString : spellContainer.spell_ids()) {
                    var id = Identifier.of(idString);
                    var spell = registry.getEntry(id).orElse(null);
                    if (spell != null && spell.value().type == Spell.Type.MODIFIER) {
                        modifiers.add(spell);
                    }
                }
            }

            ((Owner) player).setSpellContainers(new Result(activeContainer, activeSpells, passiveSpells, modifiers.stream().toList(), allContainers));

            // Containers changed — the casting authority re-derives its options from them and
            // re-declares to the owner's client (tracked data). Server-side only: on the client
            // the interactor mirrors the declared options instead of computing its own.
            if (!player.getWorld().isClient) {
                ((SpellCaster.Player) player).getInteractor().invalidateOptions();
            }
        }
    }

    public static List<RegistryEntry<Spell>> mergedContainerSources(List<SourcedContainer> sources, @Nullable SpellContainer.ContentType contentType, @Nullable String accessParams, Spell.Type type, World world) {
        if (sources.isEmpty()) {
            return List.of();
        }
        var spells = new ArrayList<RegistryEntry<Spell>>();
        var registry = SpellRegistry.from(world);

        TagKey<Spell> spellTag = null;
        if (accessParams != null && !accessParams.isEmpty()) {
            if (contentType == SpellContainer.ContentType.TAG) {
                var id = Identifier.tryParse(accessParams);
                if (id != null) {
                    spellTag = TagKey.of(SpellRegistry.KEY, id);
                }
            }
        }

        for (var source : sources) {
            var container = source.container();
            if (type == Spell.Type.ACTIVE && source.name.equals("off_hand")) {
                if (!SpellEngineMod.config.spell_container_from_offhand_any) {
                    if (!container.slotMatches(EquipmentSlot.OFFHAND.asString())) {
                        continue;
                    }
                }
            }
            for (var idString : container.spell_ids()) {
                var id = Identifier.of(idString);
                var spell = registry.getEntry(id).orElse(null);
                if (spell != null && spell.value().type == type
                        && ( spellMatchesContentType(spell, contentType, spellTag) )) {
                    spells.add(spell);
                }
            }
        }

        return spells;
    }

    private static boolean spellMatchesContentType(RegistryEntry<Spell> spellEntry, @Nullable SpellContainer.ContentType contentType, @Nullable TagKey<Spell> spellTag) {
        if (contentType == null || contentType == SpellContainer.ContentType.ANY) {
            return true;
        }
        if (contentType == SpellContainer.ContentType.TAG) {
            return spellTag != null && spellEntry.isIn(spellTag);
        }
        var spell = spellEntry.value();
        var matches = switch (spell.school.archetype) {
            case ARCHERY -> contentType == SpellContainer.ContentType.ARCHERY;
            case MAGIC, MELEE -> contentType == SpellContainer.ContentType.MAGIC;
            default -> false;
        };
        if (spell.secondary_archetype != null) {
            matches = matches || switch (spell.secondary_archetype) {
                case ARCHERY -> contentType == SpellContainer.ContentType.ARCHERY;
                case MAGIC, MELEE -> contentType == SpellContainer.ContentType.MAGIC;
                case ANY -> true;
                default -> false;
            };
        }
        return matches;
    }

    public record MergeResult(SpellContainer container, List<RegistryEntry<Spell>> spells) {
        public static final MergeResult EMPTY = new MergeResult(SpellContainer.EMPTY, List.of());
    }
    public static MergeResult mergedContainerSources1(List<SourcedContainer> sources, SpellContainer heldContainer, Spell.Type type, World world) { // FIXME: NAME
        if (sources.isEmpty() || heldContainer.access() == SpellContainer.ContentType.NONE) {
            return MergeResult.EMPTY;
        }
        if (heldContainer.access() == SpellContainer.ContentType.CONTAINED) {
            var spells = new ArrayList<RegistryEntry<Spell>>();
            var registry = SpellRegistry.from(world);
            for (var idString : heldContainer.spell_ids()) {
                var id = Identifier.of(idString);
                var spell = registry.getEntry(id).orElse(null);
                if (spell != null && spell.value().type == type) {
                    spells.add(spell);
                }
            }
            return new MergeResult(heldContainer, spells);
        }

        var contentType = heldContainer.access();

        var spells = mergedContainerSources(sources, contentType, heldContainer.access_param(), type, world);

        var spellIds = new LinkedHashSet<String>(); // We need the IDs only, but remove duplicates
        for (var spell : spells) {
            spellIds.add(spell.getKey().get().getValue().toString());
        }

        // System.out.println("Updated for " + type + ", Spell IDs: " + spellIds);

        var finalContentType = contentType != null ? contentType : SpellContainer.ContentType.NONE;
        var container = new SpellContainer(finalContentType, "", null, "", 0, new ArrayList<>(spellIds), 0);
        return new MergeResult(container, spells);
    }

    @Nullable public static SourcedContainer getFirstSourceOfSpell(Identifier spellId, PlayerEntity player) {
        var result = ((Owner)player).getSpellContainers();
        for (var source : result.sources()) {
            if (contains(source.container(), spellId)) {
                return source;
            }
        }
        return null;
    }
    private static boolean contains(SpellContainer container, Identifier spellId) {
        return container != null && container.spell_ids().contains(spellId.toString());
    }

    private static void updateEquipmentSets(PlayerEntity player, ArrayList<SourcedContainer> allContainers) {
        ArrayList<EquipmentSet.SourcedItemStack> equipmentStacks = new ArrayList<>();
        for (var entry : itemSources) {
            final var sourceName = entry.name();
            var stacks = entry.source().getSpellContainerItemStacks(player, sourceName);
            stacks.stream()
                    .map(stack -> new EquipmentSet.SourcedItemStack(stack, sourceName))
                    .forEach(equipmentStacks::add);
        }
        var equipmentSets = EquipmentSet.collectFrom(equipmentStacks, player.getWorld());
        ((EquipmentSet.Owner) player).setActiveEquipmentSets(equipmentSets);
        allContainers.addAll(sourcedContainersFrom(equipmentSets));
    }

    private static List<SourcedContainer> sourcedContainersFrom(List<EquipmentSet.Result> results) {
        var spellContainers = new ArrayList<SourcedContainer>();
        for (var result : results) {
            var set = result.set().value();
            for (var bonus: set.bonuses()) {
                if (result.items().size() >= bonus.requiredPieceCount()
                        && bonus.spells() != null) {
                    spellContainers.add(new SourcedContainer(set.name(), result.items().getFirst(), bonus.spells()));
                }
            }
        }
        return spellContainers;
    }
}

